/// <summary>
/// Kurt Scerri - 03/03/2021
/// Replication of Microsoft class <c>BankPaymAdviceReportGeneratorVend</c> due to internal class declarations
/// </summary>
class METBankPaymAdviceReportGeneratorVend extends METBankPaymAdviceReportGenerator
{
    protected SpecTrans specTrans;
    protected VendTrans vendTransInvoice;
    protected VendTable vendTable;
    private VendTransOpen vendTransOpenInvoice;
    protected VendInvoiceJour  vendInvoiceJour;

    private Name vendorName;
    private VendAccount vendorAccountNum;
    private LogisticsElectronicAddressLocator vendorContactEmail;

}

Method.Source:
    protected void findRecipient(LedgerJournalTrans _ledgerJournalTrans)
    {
        vendTable = VendTable::findByCompany(_ledgerJournalTrans.Company,
            _ledgerJournalTrans.parmAccount());

        vendorName = vendTable.name();
        vendorAccountNum = vendTable.AccountNum;
        vendorContactEmail = vendTable.email();
    }

protected void findGrouping()
{
    grouping = ledgerJournalTrans.parmAccount() + this.getPaymentCurrencyCode() + LogisticsLocation::locationNameFromRecId(ledgerJournalTrans.RemittanceLocation);
}

protected void findInvoicesAndCreateData()
{
    while select crosscompany specTrans
        where specTrans.SpecRecId == ledgerJournalTrans.RecId
            && specTrans.SpecCompany == ledgerJournalTrans.company()
            && specTrans.SpecTableId == tableNum(LedgerJournalTrans)
            && specTrans.RefTableId == tableNum(VendTransOpen)
    {
        vendTransOpenInvoice = specTrans.vendTransOpen();
        vendTransInvoice = vendTransOpenInvoice.vendTrans(); 

        this.insertBankPaymAdviceTmp();
        this.populateBankPaymAdviceTempCustInfo();
    }
}

    protected void populateBankPaymAdviceTempCommonInfo()
    {
        super();

        bankPaymAdviceTmp.CompanyAddress = companyAddress;
        bankPaymAdviceTmp.Name = vendorName;
        bankPaymAdviceTmp.AccountNum = vendorAccountNum;
        bankPaymAdviceTmp.ContactEmail = vendorContactEmail;

        if (ledgerJournalTrans.RemittanceAddress)
        {
            bankPaymAdviceTmp.Address = LogisticsPostalAddress::addressFromRecId(ledgerJournalTrans.RemittanceAddress);
        }
        else
        {
            bankPaymAdviceTmp.Address = LogisticsPostalAddress::addressFromRecId(vendTransInvoice.RemittanceAddress);
        }

        /// MPJ_2573_VendorRemittanceAdviceFormatChanges - START
        bankPaymAdviceTmp.METAccountLabel = VendTable.VendGroup == 'ZNT5' ? "@SYS68363" : "@WAX128";
        /// MPJ_2573_VendorRemittanceAdviceFormatChanges - END

    }

    protected void populateBankPaymAdviceTempPaymentInfo()
    {
        bankPaymAdviceTmp.PaymRefLabel = this.getPaymRefLabel();
        bankPaymAdviceTmp.PaymentReference = this.getPaymRef();
        bankPaymAdviceTmp.METCheque = ledgerJournalTrans.BankChequeNum;
        bankPaymAdviceTmp.SettledCurrencyCode = this.getPaymentCurrencyCode();
        bankPaymAdviceTmp.CashDisc = this.getCashDiscAmount();
        bankPaymAdviceTmp.Balance01 = abs(this.calculateAmountInPaymentCurrency(
            ledgerJournalTrans.TransDate,
            vendTransInvoice.CurrencyCode,
            -SpecTransManager::getSpecTransBalanceForTaxWithholding(specTrans)));

        bankPaymAdviceTmp.TransDate = ledgerJournalTrans.TransDate;
    }

    protected void populateBankPaymAdviceTempInvoiceInfo()
    {
        TaxTrans                taxTrans;
        MarkupTrans             markUpTrans;
        METPayPricingCondition  metPricingCondition;
        str                     metCondition;
        GeneralJournalEntry         generalJournalEntry;
        GeneralJournalAccountEntry  generalJournalAccountEntry;
        

        bankPaymAdviceTmp.Invoice = vendTransInvoice.Invoice;
        bankPaymAdviceTmp.InvoiceDate = vendTransInvoice.DocumentDate ? vendTransInvoice.DocumentDate : vendTransInvoice.TransDate;
        bankPaymAdviceTmp.CurrencyCode = vendTransInvoice.CurrencyCode;
        bankPaymAdviceTmp.AmountCur = vendTransInvoice.AmountCur;
        bankPaymAdviceTmp.InvoiceTaxWithholdAmount = -this.getInvoiceTaxWithholdAmount();
        bankPaymAdviceTmp.IsWithholdingTaxCalculated = this.getIsTaxWithholdCalculated();
        bankPaymAdviceTmp.TransId = vendTransInvoice.RecId; 
       
        //MPJ-31578 Start
        select firstonly RecId from generalJournalEntry 
                where generalJournalEntry.SUBLEDGERVOUCHER == vendTransInvoice.Voucher
            join  LedgerDimension from generalJournalAccountEntry
                where generalJournalAccountEntry.GeneralJournalEntry == generalJournalEntry.RecId ;
        
        bankPaymAdviceTmp.Branch = this.getLedgerDimensionValues(generalJournalAccountEntry.LedgerDimension,METConstants::profitCentre);
        bankPaymAdviceTmp.State = this.getLedgerDimensionValues(generalJournalAccountEntry.LedgerDimension,METConstants::state);
        //MPJ-31578 End
      
        /// MPJ_2573_VendorRemittanceAdviceFormatChanges - START
        /// Gross invoice = Invoice amount + taxes + Charges + Rebate
        /// Inv GST = Line tax amount
        /// Gorss reb = Discount + Charges + Charges Tax
        /// Reb GST = Charges Tax
        /// Net amount  = Gross invoice - Gross reb
        bankPaymAdviceTmp.METVoucher    = vendTransInvoice.Voucher;
        bankPaymAdviceTmp.METGrossReb   = abs(bankPaymAdviceTmp.CashDisc);
        bankPaymAdviceTmp.METRebGST     = 0;
        bankPaymAdviceTmp.METGrossInv   = 0;
        bankPaymAdviceTmp.METInvGST     = 0;
        changecompany(vendTransInvoice.company()) ////MPJ-31578 
        {
            //MPJ-31578 Start
            if (vendTransInvoice.JournalNum)
            {
                select SUBLEDGERVOUCHER, RecId from generalJournalEntry
                        where generalJournalEntry.SUBLEDGERVOUCHER == vendTransInvoice.Voucher
                    join  GeneralJournalEntry,sum(TransactionCurrencyAmount),PostingType from generalJournalAccountEntry
                        group by generalJournalAccountEntry.GeneralJournalEntry , generalJournalAccountEntry.PostingType
                            where generalJournalAccountEntry.GeneralJournalEntry == generalJournalEntry.RecId &&
                               !(generalJournalAccountEntry.Text like METConstants::Z) &&
                                generalJournalAccountEntry.PostingType == LedgerPostingType::LedgerJournal ;

                bankPaymAdviceTmp.METGrossInv = abs(generalJournalAccountEntry.TransactionCurrencyAmount);

                select SUBLEDGERVOUCHER, RecId from generalJournalEntry
                        where generalJournalEntry.SUBLEDGERVOUCHER == vendTransInvoice.Voucher
                    join  GeneralJournalEntry,sum(TransactionCurrencyAmount),PostingType from generalJournalAccountEntry
                        group by generalJournalAccountEntry.GeneralJournalEntry , generalJournalAccountEntry.PostingType
                            where generalJournalAccountEntry.GeneralJournalEntry == generalJournalEntry.RecId &&
                                !(generalJournalAccountEntry.Text like METConstants::Z) &&
                                generalJournalAccountEntry.PostingType == LedgerPostingType::Tax ;

                bankPaymAdviceTmp.METInvGST    = abs(generalJournalAccountEntry.TransactionCurrencyAmount);

                select SUBLEDGERVOUCHER, RecId from generalJournalEntry
                        where generalJournalEntry.SUBLEDGERVOUCHER == vendTransInvoice.Voucher
                    join  GeneralJournalEntry,sum(TransactionCurrencyAmount),PostingType from generalJournalAccountEntry
                       group by generalJournalAccountEntry.GeneralJournalEntry , generalJournalAccountEntry.PostingType
                        where generalJournalAccountEntry.GeneralJournalEntry == generalJournalEntry.RecId &&
                            generalJournalAccountEntry.Text like METConstants::Z &&
                            generalJournalAccountEntry.PostingType == LedgerPostingType::LedgerJournal ;

                bankPaymAdviceTmp.METGrossReb    = abs(generalJournalAccountEntry.TransactionCurrencyAmount);

                select SUBLEDGERVOUCHER, RecId from generalJournalEntry
                        where generalJournalEntry.SUBLEDGERVOUCHER == vendTransInvoice.Voucher
                    join  GeneralJournalEntry,sum(TransactionCurrencyAmount),PostingType from generalJournalAccountEntry
                        group by generalJournalAccountEntry.GeneralJournalEntry , generalJournalAccountEntry.PostingType
                            where generalJournalAccountEntry.GeneralJournalEntry == generalJournalEntry.RecId &&
                                generalJournalAccountEntry.Text like METConstants::Z &&
                                generalJournalAccountEntry.PostingType == LedgerPostingType::Tax ;

                bankPaymAdviceTmp.METRebGST    = abs(generalJournalAccountEntry.TransactionCurrencyAmount);
                //MPJ-31578 End
                
            }
            else // Pending vendor invoices 
            {
                //MPJ-31578
                select LedgerVoucher,InvoiceId,SalesBalance from vendInvoiceJour where vendInvoiceJour.LedgerVoucher == vendTransInvoice.Voucher &&
                                          vendInvoiceJour.InvoiceId == vendTransInvoice.Invoice  ;

                bankPaymAdviceTmp.METGrossInv   =  vendInvoiceJour.SalesBalance; //MPJ-31578
                //Include -ve charges in the invoice amount if any. We need to show the charges in the GrossReb value in the report.
                select sum(CalculatedAmount) from markUpTrans where markUpTrans.Voucher == vendTransInvoice.Voucher;

                if (markUpTrans.CalculatedAmount < 0)
                {
                    bankPaymAdviceTmp.METGrossReb  +=  abs(markUpTrans.CalculatedAmount);
                }
            
                bankPaymAdviceTmp.METGrossReb = bankPaymAdviceTmp.METGrossReb;

                //Calculate invoice tax amount
                select sum(TaxAmount), sum(TaxBaseAmount) from taxTrans
                        where taxTrans.Voucher == vendTransInvoice.Voucher &&
                        taxTrans.TransDate == vendTransInvoice.TransDate &&
                        taxTrans.SourceTableId != tableNum(MarkupTrans);
                if (taxTrans.TaxAmount)
                {
                    bankPaymAdviceTmp.METInvGST     =   taxTrans.TaxAmount;
                }

                //Calculate charges tax amount
                select sum(TaxAmount), sum(TaxBaseAmount) from taxTrans
                        where taxTrans.Voucher == vendTransInvoice.Voucher &&
                        taxTrans.TransDate == vendTransInvoice.TransDate &&
                        taxTrans.SourceTableId == tableNum(MarkupTrans);

                if (taxTrans.TaxAmount < 0)
                {
                    bankPaymAdviceTmp.METRebGST = abs(taxTrans.TaxAmount);
                }
                else
                {
                    bankPaymAdviceTmp.METInvGST += abs(taxTrans.TaxAmount);
                }
            }
        }
        bankPaymAdviceTmp.METGrossInv   = bankPaymAdviceTmp.METGrossInv == 0 ? bankPaymAdviceTmp.AmountCur :  bankPaymAdviceTmp.METGrossInv;

      
        /// MPJ_2573_VendorRemittanceAdviceFormatChanges - END
    }

    protected void populateBankPaymAdviceTempCustInfo()
    {
        if (!bankPaymAdviceTmp.Invoice)
        {
            CustTrans           custTransInvoice;
            CustTrans           custTransReiumbursement;
            CustSettlement      custSettlement;
            CustTable           custTable;

            while select  crosscompany Invoice, AccountNum, AmountCur, DueDate from  custTransInvoice
                    join RecId, SettleAmountCur from custSettlement
                    where custSettlement.OffsetRecid == custTransInvoice.RecId &&
                    custSettlement.OffsetCompany == custTransInvoice.DataAreaId &&
                    custSettlement.AccountNum == custTransInvoice.AccountNum &&
                    custSettlement.CanBeReversed == NoYes::Yes 

                    exists join RecId from custTransReiumbursement
                        where custTransReiumbursement.Voucher == vendTransInvoice.Voucher &&
                            custTransReiumbursement.RecId == custSettlement.TransRecId &&
                            custTransReiumbursement.DataAreaId == vendTransInvoice.DataAreaId &&
                            custTransReiumbursement.DataAreaId == custSettlement.TransCompany &&
                            custTransReiumbursement.AccountNum == custSettlement.AccountNum
                    
                            join RecId from custTable
                                where custTable.Party == vendTable.Party &&
                                custTable.DataAreaId == vendTable.DataAreaId &&
                                custTable.AccountNum == custTransReiumbursement.AccountNum
            {
                bankPaymAdviceCustTmp.Invoice = custTransInvoice.Invoice;
                bankPaymAdviceCustTmp.AccountNum = custTransInvoice.AccountNum;
                bankPaymAdviceCustTmp.AmountCur = custSettlement.SettleAmountCur;
                bankPaymAdviceCustTmp.TransDate = custTransInvoice.DueDate;
                bankPaymAdviceCustTmp.setExecutionContext(this.parmExecutionContext());
                bankPaymAdviceCustTmp.SessionId = currentSessionId;
                bankPaymAdviceCustTmp.insert();
            }

        }
    }

    private TaxWithholdAmountCur getInvoiceTaxWithholdAmount()
    {
        TaxWithholdTrans taxWithholdTrans;

        select sum(InvoiceTaxWithholdAmount) from taxWithholdTrans where taxWithholdTrans.VendTransInvoiceId == vendTransInvoice.RecId;

        return taxWithholdTrans.InvoiceTaxWithholdAmount;
    }

    private TaxWithholdCalculate_TH getIsTaxWithholdCalculated()
    {
        LedgerJournalTrans ledgerJournalTransInvoice;

        select firstonly TaxWithholdCalculate_TH from ledgerJournalTransInvoice where ledgerJournalTransInvoice.VendTransId == vendTransInvoice.RecId;

        return ledgerJournalTransInvoice.TaxWithholdCalculate_TH;
    }

    /// <summary>
    /// The payment reference label.
    /// </summary>
    /// <returns>The payment reference label.</returns>
    protected str getPaymRefLabel()
    {
        str paymRefLabel;

        if (ledgerJournalTrans.BankPromissoryNoteNum)
        {
            paymRefLabel = "@SYS71440";
        }
        else
        {
            paymRefLabel = super();
        }

        return paymRefLabel;
    }

    /// <summary>
    /// Gets the payment reference.
    /// </summary>
    /// <returns>The payment reference.</returns>
    protected str getPaymRef()
    {
       /* str paymRef;

        if (ledgerJournalTrans.BankPromissoryNoteNum)
        {
            paymRef = ledgerJournalTrans.BankPromissoryNoteNum;
        }
        else
        {
            paymRef = super();
        }*/

        return ledgerJournalTrans.JournalNum;
    }

/// <summary>
/// Gets the cash discount amount in the payment currency.
/// </summary>
/// <returns>The cash discount amount in the payment currency.</returns>
protected Amount getCashDiscAmount()
{
    return this.calculateAmountInPaymentCurrency(ledgerJournalTrans.TransDate, vendTransInvoice.CurrencyCode, specTrans.CashDiscToTake);
}

    [SuppressBPWarning('BPErrorClassNewNotProtected', 'Need to instantiate externally.Add construct method instead')]
    public void new()
    {
        super();

        METBankPaymAdviceVendTmp bankPaymAdviceVendTmp;
        bankPaymAdviceTmp = bankPaymAdviceVendTmp;

        METBankPaymAdviceCustTmp bankPaymAdviceCustTmpLoc;
        bankPaymAdviceCustTmp = bankPaymAdviceCustTmpLoc;
    }
